message AllocIPReply {
  bool Success = 1;
  IPType IPType = 2;
  bool IPv4 = 3;
  bool IPv6 = 4;
  repeated NetConf NetConfs = 5;   // 每个网络接口一个 NetConf
}

message NetConf {
  BasicInfo BasicInfo = 1;
  ENIInfo ENIInfo = 2;
  Pod Pod = 3;
  string IfName = 4;              // 容器内接口名
  repeated Route ExtraRoutes = 5; // 明细路由
  bool DefaultRoute = 6;          // 是否为默认路由
}
